package com.orderpilot.core.ai;

/** Outcome of summarising an order: generated by the LLM, or the deterministic template (by design or as fallback). */
public sealed interface SummaryResult {

    String text();

    record Generated(String text, String provider) implements SummaryResult {
    }

    record Template(String text, String reason) implements SummaryResult {
    }
}
